    /** SHA-256 of the link token, lowercase hex, no pepper; the plaintext token is never stored. redeemLinkToken finds the session with a collection-group query on this field (x-decisions Q-TOKEN-HASH, Q-LINK-FORMAT). */
    @get:PropertyName("link_token_hash") @set:PropertyName("link_token_hash")
    var linkTokenHash: String = "",
    /** The first browser to redeem the link becomes the session's viewer (role viewer); null until the first open. Only it can share back or see Ask to share. */
    @get:PropertyName("viewer_uid") @set:PropertyName("viewer_uid")
    var viewerUid: String? = null,
    /** The optional "who it's for" name, used only on the sharer's screens; null when not given. */
    @get:PropertyName("viewer_name") @set:PropertyName("viewer_name")
    var viewerName: String? = null,
    /** iOS only: this session's Live Activity update token, for Live Activity updates over APNs. Null on Android or before the activity starts (x-decisions Q-DEVICE-ID). */
    @get:PropertyName("activity_push_token") @set:PropertyName("activity_push_token")
    var activityPushToken: String? = null,
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val USER_ID = "user_id"
        const val LINK_TOKEN_HASH = "link_token_hash"
        const val VIEWER_UID = "viewer_uid"
        const val VIEWER_NAME = "viewer_name"
        const val ACTIVITY_PUSH_TOKEN = "activity_push_token"
    }
}

/** One location. pings: the sharer's, which the viewer's map listens to. viewerPings: the viewer's, written only while they share back; the sharer's app listens to them. Both are deleted 24 hours after the session ends (FSD §6, §8). While the sharer is approximate, lat/lng are already rounded to about 500 m on the phone; precision lives on the session, not on each ping. firestore.rules accept a ping write only with exactly these four fields, lat/lng in range, 0 ≤ accuracy_m ≤ MAX_ACCURACY_METERS, recorded_at no later than server time + PING_CLOCK_SKEW_SECONDS, a doc id of 1 to PING_ID_MAX_LENGTH characters [A-Za-z0-9_-], on a session that is active and before both stop_at and expires_at. The sharer's pings also go in one batch with the session's check-in and last_fix_at, in order and at least 2 s apart (x-decisions Q-PING-WRITE). Firestore: shareSessions/{sessionId}/pings/{pingId} and shareSessions/{sessionId}/viewerPings/{pingId}. */
data class Ping(
    /** Latitude, WGS 84 degrees. */
    @get:PropertyName("lat") @set:PropertyName("lat")
    var lat: Double = 0.0,
    /** Longitude, WGS 84 degrees. */
    @get:PropertyName("lng") @set:PropertyName("lng")
    var lng: Double = 0.0,
    /** The fix's horizontal accuracy in meters, as the platform reports it. While the sharer is approximate it is max(raw accuracy, 500), matching the rounded point; firestore.rules reject a ping under 500 while the session (as written in the same batch, so a precision_next change counts) is approximate (x-decisions Q-PING-FIELDS, Q-ACCURACY-APPROX). */
    @get:PropertyName("accuracy_m") @set:PropertyName("accuracy_m")
    var accuracyM: Double = 0.0,
    /** When the fix was taken. Last seen always uses the newest ping's recorded_at. */
    @get:PropertyName("recorded_at") @set:PropertyName("recorded_at")
    var recordedAt: Timestamp = Timestamp(0, 0),
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val LAT = "lat"
        const val LNG = "lng"
        const val ACCURACY_M = "accuracy_m"
        const val RECORDED_AT = "recorded_at"
    }
}

/** Base character library: the set it belongs to and the accessories each one supports (FSD §6, §11). The doc id is the MascotId. Firestore: mascots/{mascotId}. */
data class Mascot(
    /** The mascot id ('fox'), the same as the doc id. Display names live in the apps' strings (x-decisions Q-MASCOT-CHARACTER). */
    @get:PropertyName("character") @set:PropertyName("character")
    var character: MascotId = MascotId.FOX,
    /** Classics, Anime or Movie night. */
    @get:PropertyName("set") @set:PropertyName("set")
    var set: MascotSet = MascotSet.CLASSICS,
    /** original for every character in v1. */
    @get:PropertyName("default_color") @set:PropertyName("default_color")
    var defaultColor: MascotColor = MascotColor.ORIGINAL,
    /** The accessories it takes (FSD §11 matrix; the astronaut takes none). */
    @get:PropertyName("accessories") @set:PropertyName("accessories")
    var accessories: List<MascotAccessory> = emptyList(),
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val CHARACTER = "character"
        const val SET = "set"
        const val DEFAULT_COLOR = "default_color"
        const val ACCESSORIES = "accessories"
    }
}

/** One per browser sign-in that redeemLinkToken minted for this session (the doc id is that Auth uid), viewer and watchers alike, written in the transaction that decides the role. Function-only: clients can't read or write it. The 24-hour cleanup deletes these Auth users, then these docs (FSD §8 Retention; x-decisions Q-VIEWER-SIGNINS). Firestore: shareSessions/{sessionId}/viewerSignIns/{viewerUid}. */
data class ViewerSignIn(
    /** The role minted for this uid: viewer for the first browser, watcher for any later one. */
    @get:PropertyName("role") @set:PropertyName("role")
    var role: ViewerRole = ViewerRole.VIEWER,
    /** Server timestamp of the first redeem by this uid. */
    @get:PropertyName("created_at") @set:PropertyName("created_at")
    var createdAt: Timestamp = Timestamp(0, 0),
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val ROLE = "role"
        const val CREATED_AT = "created_at"
    }
}

/** Function-only: makes each alert fire once per session, however often its trigger runs (x-decisions Q-ALERT-ONCE). Deleted with the session (30-day purge, deleteAccount, discardSession). Firestore: shareSessions/{sessionId}/alerts/{kind}. */
data class AlertDelivery(
    /** Which alert; also the doc id. */
    @get:PropertyName("kind") @set:PropertyName("kind")
    var kind: AlertKind = AlertKind.LINK_OPENED,
    /** sending while an attempt holds lease_until or a retry is due; sent once every device was tried; skipped when the user's alert setting was off. */
    @get:PropertyName("state") @set:PropertyName("state")
    var state: String = "",
    /** users/{userId}/devices ids FCM accepted the alert for, so a retry never sends to them twice. */
    @get:PropertyName("delivered") @set:PropertyName("delivered")
    var delivered: List<String> = emptyList(),
    /** Attempts that claimed the alert. */
    @get:PropertyName("attempts") @set:PropertyName("attempts")
    var attempts: Int = 0,
    /** Until then an attempt is in flight and no other may send. */
    @get:PropertyName("lease_until") @set:PropertyName("lease_until")
    var leaseUntil: Timestamp = Timestamp(0, 0),
    /** When the first attempt claimed it. */
    @get:PropertyName("created_at") @set:PropertyName("created_at")
    var createdAt: Timestamp = Timestamp(0, 0),
    /** Server timestamp of the last change. */
    @get:PropertyName("updated_at") @set:PropertyName("updated_at")
    var updatedAt: Timestamp = Timestamp(0, 0),
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val KIND = "kind"
        const val STATE = "state"
        const val DELIVERED = "delivered"
        const val ATTEMPTS = "attempts"
        const val LEASE_UNTIL = "lease_until"
        const val CREATED_AT = "created_at"
        const val UPDATED_AT = "updated_at"
    }
}

/** Links a call to the session it started with; kept 30 days like session metadata (FSD §6, §8). createSession writes it for a call-triggered share, in the same transaction, with callLogId = the session id (each session has at most one call), and the 30-day purge deletes it with the session. Clients can't read or write it (x-decisions Q-CALLLOG-ID). Firestore: callLogs/{callLogId}. */
data class CallLog(
    /** The sharer's userId. */
    @get:PropertyName("user_id") @set:PropertyName("user_id")
    var userId: String = "",
    /** The shareSessions doc id. */
    @get:PropertyName("session_id") @set:PropertyName("session_id")
    var sessionId: String = "",
    /** The call's per-device unique id (the CallKit UUID on iOS, a generated UUID on Android), as stored in shareSessions.call_id. */
    @get:PropertyName("call_id") @set:PropertyName("call_id")
    var callId: String = "",
    /** Server timestamp of when the call was first seen (x-decisions Q-CALL-TIME). */
    @get:PropertyName("call_time") @set:PropertyName("call_time")
    var callTime: Timestamp = Timestamp(0, 0),
) {
    /** Firestore field names, for queries and partial updates. */
    object Fields {
        const val USER_ID = "user_id"
        const val SESSION_ID = "session_id"
        const val CALL_ID = "call_id"
        const val CALL_TIME = "call_time"
    }
}

/** The viewer's shared-back location: same shape as a ping, in shareSessions/{sessionId}/viewerPings. */
typealias ViewerPing = Ping

// ---------- Callable payloads ----------

/** Callable createSession, request: the payload agreed between the apps and code/backend from FSD §4 (Live map link, Stop rule, Let them share back, Location detail, Who it's for) and §5. The server takes the sharer snapshot from users/{uid}, sets expires_at = started_at + 1 hour, last_ping_at = started_at and ping_interval_s = 5, and computes stop_at. One session at a time: when users.active_session_id points to a live session, the call fails with already-exists and details {reason: "active_session", session_id}; a stale pointer (stopped, expired or deleted session) doesn't block. Callable: createSession (request). */
data class CreateSessionRequest(
    /** call only during a call (call_id set). */
    val stopRule: StopRule,
    /** Required when stop_rule is minutes, otherwise null. Choices that would end after expires_at aren't offered. */
    val stopMinutes: StopMinutes?,
    /** The connected call's per-device id, or null for a manual share. */
    val callId: String?,
    /** The share screen's switch. The server forces false without a call. */
    val shareBackAllowed: Boolean,
    /** Precise or approximate. */
    val precision: Precision,
    /** Optional "who it's for" name, trimmed; stored in private/meta.viewer_name and users.last_viewer_name. */
    val viewerName: String? = null,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("stop_rule", stopRule.wire)
        put("stop_minutes", stopMinutes?.minutes)
        put("call_id", callId)
        put("share_back_allowed", shareBackAllowed)
        put("precision", precision.wire)
        if (viewerName != null) put("viewer_name", viewerName)
    }
}

/** Callable createSession, response. link_token is returned once, in plaintext; only its hash is stored (private/meta.link_token_hash). Callable: createSession (response). */
data class CreateSessionResponse(
    /** The new shareSessions doc id. */
    val sessionId: String,
    /** The link token, plaintext, returned only here. */
    val linkToken: String,
    /** The share link, <viewer origin>/s/<token> (https://trackme.live/s/<token> in production), built by the server so the apps don't hard-code the host. */
    val linkUrl: String,
    /** started_at, epoch ms. */
    val startedAt: Long,
    /** expires_at, epoch ms. */
    val expiresAt: Long,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): CreateSessionResponse = CreateSessionResponse(
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
            linkToken = requireNotNull(map["link_token"] as String?) { "link_token is missing" },
            linkUrl = requireNotNull(map["link_url"] as String?) { "link_url is missing" },
            startedAt = requireNotNull((map["started_at"] as Number?)?.toLong()) { "started_at is missing" },
            expiresAt = requireNotNull((map["expires_at"] as Number?)?.toLong()) { "expires_at is missing" },
        )
    }
}

/** Callable redeemLinkToken, request: the viewer page's own script sends the token from location.pathname (/s/<token>). It's the only way to look a token up; clients never query by it, and link previews never call it (FSD §6 Viewer access). Callable: redeemLinkToken (request). */
data class RedeemLinkTokenRequest(
    /** The token from the link. */
    val linkToken: String,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("link_token", linkToken)
    }
}

/** Callable redeemLinkToken, response. The function hashes the token, finds the active session, sets first_viewed_at and the view notification on the first open, records the first browser as viewer_uid, and returns a custom token carrying the {sid, role} claims (ViewerClaims). The page signs in with it, so it never reads the private doc. Errors: not-found for any token that matches no session (malformed or unknown, with the same message). A session that has stopped, or passed stop_at or expires_at, fails with failed-precondition and details {reason: 'session_ended', sharer: SharerSnapshot}; no custom token is minted, so nothing can read pings, and the page shows 'This location is no longer being shared' with the mascot. A browser that redeems again with its own viewer sign-in (sid claim for this session) keeps its uid and role. A new browser once the session already has MAX_VIEWER_SIGN_INS sign-ins gets resource-exhausted with details {reason: 'too_many_viewers'}; the page shows 'This link can't be opened right now'. Callable: redeemLinkToken (response). */
data class RedeemLinkTokenResponse(
    /** Firebase custom token for signInWithCustomToken, minted per browser, with the ViewerClaims {sid, role}. */
    val customToken: String,
    /** The shareSessions doc id to listen to. */
    val sessionId: String,
    /** viewer for the first browser, watcher after that. */
    val role: ViewerRole,
    /** True when role is viewer and the session allows share back right now (share_back_allowed and call_active). The page keeps following the session doc for later changes. */
    val canShareBack: Boolean,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): RedeemLinkTokenResponse = RedeemLinkTokenResponse(
            customToken = requireNotNull(map["custom_token"] as String?) { "custom_token is missing" },
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
            role = requireNotNull(ViewerRole.fromWire(map["role"] as String?)) { "role is missing" },
            canShareBack = requireNotNull(map["can_share_back"] as Boolean?) { "can_share_back is missing" },
        )
    }
}

/** Callable saveProfile, request: creates or updates the caller's users/{uid} (FSD §4 Sign up, Settings; §6). Phone sign-in only. The app sends the whole profile it shows; the server trims name. settings is optional: omitted, it keeps the stored settings, or DEFAULT_USER_SETTINGS for a new profile. last_viewer_name, active_session_id, created_at and updated_at are server-owned and rejected here. Errors: unauthenticated (signed out), permission-denied (not a phone sign-in), invalid-argument with details.errors[] {field, message}. Callable: saveProfile (request). */
data class SaveProfileRequest(
    /** The user's name. The server trims it, then it must be 1–24 grapheme clusters. */
    val name: String,
    /** The chosen mascot; fox for a new account that hasn't picked one. */
    val mascotId: MascotId,
    /** The chosen color; original by default. */
    val mascotColor: MascotColor,
    /** The chosen accessory, or null for none. Must be one the mascot takes (MASCOT_CATALOG); the server rejects any other. */
    val mascotAccessory: MascotAccessory?,
    /** The whole settings object. Omitted, the stored settings stay; a new profile gets DEFAULT_USER_SETTINGS. */
    val settings: UserSettings? = null,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("name", name)
        put("mascot_id", mascotId.wire)
        put("mascot_color", mascotColor.wire)
        put("mascot_accessory", mascotAccessory?.wire)
        if (settings != null) put("settings", settings.toWireMap())
    }
}

/** Callable saveProfile, response: the profile as stored in users/{uid}, with created_at and updated_at in epoch ms. Callable: saveProfile (response). */
data class SaveProfileResponse(
    /** The stored name, trimmed. */
    val name: String,
    /** The stored mascot. */
    val mascotId: MascotId,
    /** The stored color. */
    val mascotColor: MascotColor,
    /** The stored accessory, or null for none. */
    val mascotAccessory: MascotAccessory?,
    /** The last "who it's for" name (set by createSession), or null. */
    val lastViewerName: String?,
    /** The stored settings. */
    val settings: UserSettings,
    /** The active shareSessions id (function-owned), or null when not sharing. */
    val activeSessionId: String?,
    /** created_at, epoch ms. */
    val createdAt: Long,
    /** updated_at, epoch ms. */
    val updatedAt: Long,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): SaveProfileResponse = SaveProfileResponse(
            name = requireNotNull(map["name"] as String?) { "name is missing" },
            mascotId = requireNotNull(MascotId.fromWire(map["mascot_id"] as String?)) { "mascot_id is missing" },
            mascotColor = requireNotNull(MascotColor.fromWire(map["mascot_color"] as String?)) { "mascot_color is missing" },
            mascotAccessory = MascotAccessory.fromWire(map["mascot_accessory"] as String?),
            lastViewerName = map["last_viewer_name"] as String?,
            settings = UserSettings.fromWireMap(requireNotNull(map["settings"] as Map<*, *>?) { "settings is missing" }),
            activeSessionId = map["active_session_id"] as String?,
            createdAt = requireNotNull((map["created_at"] as Number?)?.toLong()) { "created_at is missing" },
            updatedAt = requireNotNull((map["updated_at"] as Number?)?.toLong()) { "updated_at is missing" },
        )
    }
}

/** Callable deleteAccount, request: no fields. Settings › Delete account and all data (FSD §4 Settings, §8 Deletion). Phone sign-in only. Stops any active session (end_reason stopped), then deletes users/{uid} with its devices, every session the caller owns with private/meta, pings, viewerPings and viewerSignIns (and those viewer Auth users), the caller's callLogs, and last the caller's Auth user. Idempotent: calling it again finishes anything a failed run left. The app signs out afterwards. Errors: unauthenticated, permission-denied (not a phone sign-in), invalid-argument (any field sent). Callable: deleteAccount (request). */
data object DeleteAccountRequest {
    /** The callable payload: no fields. */
    fun toMap(): Map<String, Any?> = emptyMap()
}

/** Callable deleteAccount, response. Callable: deleteAccount (response). */
data class DeleteAccountResponse(
    /** How many of the caller's sessions this call deleted (0 on a repeat call). */
    val sessionsDeleted: Int,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): DeleteAccountResponse = DeleteAccountResponse(
            sessionsDeleted = requireNotNull((map["sessions_deleted"] as Number?)?.toInt()) { "sessions_deleted is missing" },
        )
    }
}

/** Callable stopSession, request: the sharer taps Stop (FSD §4 Stop sharing). Phone sign-in, owner only. Ends the session now with end_reason stopped, sets viewer_sharing false and clears users.active_session_id, in one transaction. Idempotent: a session that has already ended (or is past stop_at or expires_at, which ends it as timer or limit) returns how it ended. Errors: unauthenticated, permission-denied (not a phone sign-in), invalid-argument with details.errors[] {field, message}, not-found (no such session, or not the caller's). Callable: stopSession (request). */
data class StopSessionRequest(
    /** The shareSessions doc id from createSession. */
    val sessionId: String,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("session_id", sessionId)
    }
}

/** Callable stopSession, response: how the session ended. Callable: stopSession (response). */
data class StopSessionResponse(
    /** The session. */
    val sessionId: String,
    /** ended_at, epoch ms. */
    val endedAt: Long,
    /** stopped, unless it had already ended another way. */
    val endReason: EndReason,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): StopSessionResponse = StopSessionResponse(
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
            endedAt = requireNotNull((map["ended_at"] as Number?)?.toLong()) { "ended_at is missing" },
            endReason = requireNotNull(EndReason.fromWire(map["end_reason"] as String?)) { "end_reason is missing" },
        )
    }
}

/** Callable reportCallEnded, request: the app saw the session's call end (FSD §4 Auto-expiry, §9 Call drops mid-share). Phone sign-in, owner only, and call_id must be the session's call_id. Sets call_ended_at, call_active false and viewer_sharing false; when stop_rule is call it also ends the session (end_reason call) and clears users.active_session_id. After this, call_active can never be true again for the session. Idempotent: a second report, or one for a session that has already ended, changes nothing and returns the state. Errors: unauthenticated, permission-denied, invalid-argument, not-found, and failed-precondition with details {reason: 'no_call'} (a manual share) or {reason: 'call_mismatch'} (another call). Callable: reportCallEnded (request). */
data class ReportCallEndedRequest(
    /** The shareSessions doc id. */
    val sessionId: String,
    /** The call that ended: the same per-device id sent to createSession. */
    val callId: String,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("session_id", sessionId)
        put("call_id", callId)
    }
}

/** Callable reportCallEnded, response: the session after the report. Callable: reportCallEnded (response). */
data class ReportCallEndedResponse(
    /** The session. */
    val sessionId: String,
    /** stopped when the stop rule was the call (or the session had already ended); active when a timer keeps it going. */
    val status: SessionStatus,
    /** call_ended_at, epoch ms; null only when the session had already ended before the call did. */
    val callEndedAt: Long?,
    /** ended_at, epoch ms, when stopped; null while active. */
    val endedAt: Long?,
    /** Why it ended, when stopped; null while active. */
    val endReason: EndReason?,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): ReportCallEndedResponse = ReportCallEndedResponse(
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
            status = requireNotNull(SessionStatus.fromWire(map["status"] as String?)) { "status is missing" },
            callEndedAt = (map["call_ended_at"] as Number?)?.toLong(),
            endedAt = (map["ended_at"] as Number?)?.toLong(),
            endReason = EndReason.fromWire(map["end_reason"] as String?),
        )
    }
}

/** Callable reportCallActive, request: pings have resumed and the platform still reports the session's call connected, after the watchdog cleared call_active (FSD §6: a signal gap must not end share back for the rest of the call). Phone sign-in, owner only. Succeeds only while the session is active and before stop_at and expires_at, call_id matches and call_ended_at is null; it sets call_active true and last_ping_at to server time. Idempotent. Errors: unauthenticated, permission-denied, invalid-argument, not-found, and failed-precondition with details {reason}: 'session_ended', 'no_call' (a manual share), 'call_mismatch', or 'call_ended' (call_ended_at is set, so call_active never comes back). Callable: reportCallActive (request). */
data class ReportCallActiveRequest(
    /** The shareSessions doc id. */
    val sessionId: String,
    /** The connected call: the same per-device id sent to createSession. */
    val callId: String,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("session_id", sessionId)
        put("call_id", callId)
    }
}

/** Callable reportCallActive, response. Callable: reportCallActive (response). */
data class ReportCallActiveResponse(
    /** The session. */
    val sessionId: String,
    /** The check-in time it wrote, epoch ms (server time). */
    val lastPingAt: Long,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): ReportCallActiveResponse = ReportCallActiveResponse(
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
            lastPingAt = requireNotNull((map["last_ping_at"] as Number?)?.toLong()) { "last_ping_at is missing" },
        )
    }
}

/** Callable discardSession, request: the share sheet closed without a choice, so the session is deleted before anyone can see it (FSD §4 Live map link). Phone sign-in, owner only, and only while first_viewed_at is null. Deletes the session, private/meta, its pings and its callLogs entry, and clears users.active_session_id. Errors: unauthenticated, permission-denied, invalid-argument, not-found (no such session, not the caller's, or already discarded: treat not-found on a retry as done), and failed-precondition with details {reason: 'link_opened'} once the link has been opened. Callable: discardSession (request). */
data class DiscardSessionRequest(
    /** The shareSessions doc id from createSession. */
    val sessionId: String,
) {
    /** The callable payload, with snake_case keys. */
    fun toMap(): Map<String, Any?> = buildMap {
        put("session_id", sessionId)
    }
}

/** Callable discardSession, response. Callable: discardSession (response). */
data class DiscardSessionResponse(
    /** The deleted session. */
    val sessionId: String,
) {
    companion object {
        /** Reads the callable result (`HttpsCallableResult.getData()`). */
        fun fromMap(map: Map<*, *>): DiscardSessionResponse = DiscardSessionResponse(
            sessionId = requireNotNull(map["session_id"] as String?) { "session_id is missing" },
        )
    }
}

/** Callable function names. */
object TmlCallables {
    const val CREATE_SESSION = "createSession"
    const val REDEEM_LINK_TOKEN = "redeemLinkToken"
    const val SAVE_PROFILE = "saveProfile"
    const val DELETE_ACCOUNT = "deleteAccount"
    const val STOP_SESSION = "stopSession"
    const val REPORT_CALL_ENDED = "reportCallEnded"
    const val REPORT_CALL_ACTIVE = "reportCallActive"
    const val DISCARD_SESSION = "discardSession"
}

// ---------- Firestore paths ----------

/** Document and collection paths (FSD §6). */
object TmlPaths {
    /** users/{userId} */
    fun user(userId: String): String = "users/$userId"
    /** The collection holding users/{userId}. */
    fun userCollection(): String = "users"
    /** users/{userId}/devices/{deviceId} */
    fun device(userId: String, deviceId: String): String = "users/$userId/devices/$deviceId"
    /** The collection holding users/{userId}/devices/{deviceId}. */
    fun deviceCollection(userId: String): String = "users/$userId/devices"
    /** users/{userId}/trustedContacts/{contactId} */
    fun trustedContact(userId: String, contactId: String): String = "users/$userId/trustedContacts/$contactId"
    /** The collection holding users/{userId}/trustedContacts/{contactId}. */
    fun trustedContactCollection(userId: String): String = "users/$userId/trustedContacts"
    /** shareSessions/{sessionId} */
    fun shareSession(sessionId: String): String = "shareSessions/$sessionId"
    /** The collection holding shareSessions/{sessionId}. */
    fun shareSessionCollection(): String = "shareSessions"
    /** shareSessions/{sessionId}/private/meta */
    fun sessionPrivateMeta(sessionId: String): String = "shareSessions/$sessionId/private/meta"
    /** The collection holding shareSessions/{sessionId}/private/meta. */
    fun sessionPrivateMetaCollection(sessionId: String): String = "shareSessions/$sessionId/private"
    /** shareSessions/{sessionId}/pings/{pingId} */
    fun ping(sessionId: String, pingId: String): String = "shareSessions/$sessionId/pings/$pingId"
    /** The collection holding shareSessions/{sessionId}/pings/{pingId}. */
    fun pingCollection(sessionId: String): String = "shareSessions/$sessionId/pings"
    /** shareSessions/{sessionId}/viewerPings/{pingId} */
    fun viewerPing(sessionId: String, pingId: String): String = "shareSessions/$sessionId/viewerPings/$pingId"
    /** The collection holding shareSessions/{sessionId}/viewerPings/{pingId}. */
    fun viewerPingCollection(sessionId: String): String = "shareSessions/$sessionId/viewerPings"
    /** shareSessions/{sessionId}/viewerSignIns/{viewerUid} */
    fun viewerSignIn(sessionId: String, viewerUid: String): String = "shareSessions/$sessionId/viewerSignIns/$viewerUid"
    /** The collection holding shareSessions/{sessionId}/viewerSignIns/{viewerUid}. */
    fun viewerSignInCollection(sessionId: String): String = "shareSessions/$sessionId/viewerSignIns"
    /** shareSessions/{sessionId}/alerts/{kind} */
    fun alertDelivery(sessionId: String, kind: String): String = "shareSessions/$sessionId/alerts/$kind"
    /** The collection holding shareSessions/{sessionId}/alerts/{kind}. */
    fun alertDeliveryCollection(sessionId: String): String = "shareSessions/$sessionId/alerts"
    /** mascots/{mascotId} */
    fun mascot(mascotId: String): String = "mascots/$mascotId"
    /** The collection holding mascots/{mascotId}. */
    fun mascotCollection(): String = "mascots"
    /** callLogs/{callLogId} */
    fun callLog(callLogId: String): String = "callLogs/$callLogId"
    /** The collection holding callLogs/{callLogId}. */
    fun callLogCollection(): String = "callLogs"
}

// ---------- Constants (FSD values) ----------

object TmlSchemaConstants {
    /** Names are 1–24 grapheme clusters after trimming; typing stops at 24. (FSD §4 Sign up, Who it's for) */
    const val NAME_MAX_LENGTH = 24
    /** Hard limit: expires_at = started_at + 60 minutes. (FSD §4 Auto-expiry) */
    const val SESSION_LIMIT_MINUTES = 60
    /** Default timer without a call, or on Android without the Phone permission. (FSD §4 Stop rule) */
    const val DEFAULT_STOP_MINUTES = 30
    /** createSession writes ping_interval_s = 5 until the app writes the interval in use. (FSD §4 Battery-aware pings; x-decisions Q-PING-INTERVAL-INIT) */
    const val INITIAL_PING_INTERVAL_SECONDS = 5
    /** The quiet "Sharing stops at …" line appears 5 minutes before expires_at. (FSD §4 1-hour warning) */
    const val EXPIRY_WARNING_MINUTES = 5
    /** The app refreshes last_ping_at at least every 30 seconds, even without a GPS fix. (FSD §6 Design decisions) */
    const val CHECK_IN_INTERVAL_SECONDS = 30
    /** Viewer writes need last_ping_at under 2 minutes old. (FSD §6 Viewer access) */
    const val SHARE_BACK_FRESHNESS_SECONDS = 120
    /** If the app is killed or offline for 2 minutes, a scheduled function clears call_active. (FSD §6 Design decisions) */
    const val WATCHDOG_TIMEOUT_SECONDS = 120
    /** With the call stop rule, the session stops 10 minutes after the watchdog clears call_active. (FSD §4 Auto-expiry, §9) */
    const val CALL_STOP_GRACE_MINUTES = 10
    /** Never fewer than 1 ping per 60 s while active. (FSD §4 Battery-aware pings, §7) */
    const val MAX_PING_INTERVAL_SECONDS = 60
    /** firestore.rules: each ping's recorded_at is at least 2 s after the previous one's (shareSessions.last_fix_at). The fastest cadence is a ping every 3 s, so 1 s of jitter is allowed. (FSD §4 Battery-aware pings, §7; x-decisions Q-PING-WRITE) */
    const val MIN_PING_SPACING_SECONDS = 2
    /** firestore.rules: a ping's recorded_at may be at most 60 s ahead of the server's time (pings and viewerPings). (FSD §7; x-decisions Q-PING-WRITE) */
    const val PING_CLOCK_SKEW_SECONDS = 60
    /** firestore.rules: a session's first ping may be recorded at most 5 minutes before started_at (a fix taken just before Share, or a phone clock a little behind). (FSD §7; x-decisions Q-PING-WRITE) */
    const val FIRST_PING_BEFORE_START_MINUTES = 5
    /** firestore.rules: accuracy_m is at most 100 km (pings and viewerPings); anything coarser isn't a location. (FSD §6; x-decisions Q-PING-WRITE) */
    const val MAX_ACCURACY_METERS = 100000
    /** firestore.rules: ping and viewer ping doc ids are 1 to 64 characters of [A-Za-z0-9_-]; Firestore's auto ids (20 characters) fit. (FSD §6; x-decisions Q-PING-WRITE) */
    const val PING_ID_MAX_LENGTH = 64
    /** From 20% to 10% battery. (FSD §4 Battery-aware pings) */
    const val PING_INTERVAL_LOW_BATTERY_SECONDS = 15
    /** Under 10% battery. (FSD §4 Battery-aware pings) */
    const val PING_INTERVAL_CRITICAL_BATTERY_SECONDS = 60
    /** Above this, a ping every 3–5 s. (FSD §4 Battery-aware pings) */
    const val LOW_BATTERY_PERCENT = 20
    /** Under this, a ping every 60 s. (FSD §4 Battery-aware pings) */
    const val CRITICAL_BATTERY_PERCENT = 10
    /** A person shows as Live while their newest ping is under 3 ping intervals old… (FSD §7 Offline behavior) */
    const val LIVE_STALE_PING_INTERVALS = 3
    /** …and at least 15 s; then "Last seen". (FSD §7 Offline behavior) */
    const val LIVE_STALE_MIN_SECONDS = 15
    /** The sharer's app shows No GPS signal after 30 s without a fix better than 100 m. (FSD §7 Offline behavior) */
    const val NO_FIX_TIMEOUT_SECONDS = 30
    /** A fix counts when it is better than 100 m. (FSD §7 Offline behavior) */
    const val NO_FIX_ACCURACY_METERS = 100
    /** Approximate rounds each point to about 500 m on the phone. (FSD §4 Location detail) */
    const val APPROXIMATE_ROUNDING_METERS = 500
    /** Both maps show a soft circle 1 km across around the rounded point. (FSD §4 Location detail) */
    const val APPROXIMATE_CIRCLE_DIAMETER_METERS = 1000
    /** pings and viewerPings are deleted 24 hours after the session ends. (FSD §6, §8 Retention) */
    const val PING_RETENTION_HOURS = 24
    /** Session metadata and call logs are purged after 30 days. (FSD §8 Retention) */
    const val METADATA_RETENTION_DAYS = 30
    /** The text code has 6 digits. (FSD §4 Sign up) */
    const val OTP_LENGTH = 6
    /** A new code can be sent after 30 seconds. (FSD §4 Sign up) */
    const val OTP_RESEND_SECONDS = 30
    /** The link token is 128 random bits… (FSD §6 Viewer access; x-decisions Q-TOKEN-HASH) */
    const val LINK_TOKEN_BITS = 128
    /** …in base64url without padding: 22 characters. (FSD §6 Viewer access; x-decisions Q-TOKEN-HASH) */
    const val LINK_TOKEN_LENGTH = 22
    /** redeemLinkToken mints at most 10 browser sign-ins per session (viewer plus watchers, counted from viewerSignIns). A new browser past that gets resource-exhausted {reason: 'too_many_viewers'}; a browser that already has a sign-in can still refresh. (FSD §6 Viewer access; lead decision Oct 18 (abuse cap)) */
    const val MAX_VIEWER_SIGN_INS = 10
    /** Share links are <viewer origin>/s/<token>; the apps never claim this path for universal links or App Links. (FSD §4 Live map link; x-decisions Q-LINK-FORMAT) */
    const val SHARE_LINK_PATH = "/s/"
}

// ---------- Mascot catalog ----------

data class MascotCatalogEntry(val id: MascotId, val set: MascotSet, val accessories: List<MascotAccessory>)

/** The v1 mascot library (FSD §11), for seeding mascots/{id} and for the pickers. Accessory support matches mascots/model/accessories.mjs ACCESSORY_SUPPORT and the prototype's ACC_FOR. */
object MascotCatalog {
    val all: List<MascotCatalogEntry> = listOf(
        MascotCatalogEntry(MascotId.FOX, MascotSet.CLASSICS, listOf(MascotAccessory.HEADPHONES, MascotAccessory.GLASSES, MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.GHOST, MascotSet.CLASSICS, listOf(MascotAccessory.HEADPHONES, MascotAccessory.GLASSES, MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.ROBOT, MascotSet.CLASSICS, listOf(MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.ASTRONAUT, MascotSet.CLASSICS, listOf()),
        MascotCatalogEntry(MascotId.HERO, MascotSet.ANIME, listOf(MascotAccessory.GLASSES)),
        MascotCatalogEntry(MascotId.STAR, MascotSet.ANIME, listOf(MascotAccessory.HEADPHONES, MascotAccessory.GLASSES, MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.NINJA, MascotSet.ANIME, listOf(MascotAccessory.HEADPHONES)),
        MascotCatalogEntry(MascotId.NEKO, MascotSet.ANIME, listOf(MascotAccessory.GLASSES, MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.ACE, MascotSet.MOVIE, listOf(MascotAccessory.HEADPHONES, MascotAccessory.HEADLAMP)),
        MascotCatalogEntry(MascotId.DETECTIVE, MascotSet.MOVIE, listOf(MascotAccessory.GLASSES)),
        MascotCatalogEntry(MascotId.COWBOY, MascotSet.MOVIE, listOf(MascotAccessory.GLASSES)),
        MascotCatalogEntry(MascotId.AGENT, MascotSet.MOVIE, listOf(MascotAccessory.HEADPHONES, MascotAccessory.GLASSES, MascotAccessory.HEADLAMP)),
    )
    val DEFAULT_MASCOT: MascotId = MascotId.FOX
    val DEFAULT_COLOR: MascotColor = MascotColor.ORIGINAL

    /** The accessories a mascot takes. */
    fun accessoriesFor(id: MascotId): List<MascotAccessory> = all.firstOrNull { it.id == id }?.accessories.orEmpty()

    /** True when the accessory (or none) fits the mascot. */
    fun takes(id: MascotId, accessory: MascotAccessory?): Boolean = accessory == null || accessory in accessoriesFor(id)
}
